import xorshift32 = require( './index' );


// TESTS //

// The function returns a number...
{
	xorshift32(); // $ExpectType number
}

// The compiler throws an error if the function is provided any arguments...
{
	xorshift32( true ); // $ExpectError
	xorshift32( 2, 3 ); // $ExpectError
}

// The function has a normalized method which returns a number...
{
	xorshift32.normalized(); // $ExpectType number
}

// The compiler throws an error if the normalized method is provided any arguments...
{
	xorshift32.normalized( 1 ); // $ExpectError
	xorshift32.normalized( 1, 2 ); // $ExpectError
}

// Attached to main export is a `factory` method which returns a function...
{
	xorshift32.factory(); // $ExpectType NullaryFunction
	xorshift32.factory( { 'copy': false } ); // $ExpectType NullaryFunction
}

// The `factory` method returns a function which returns a number...
{
	const fcn = xorshift32.factory();
	fcn(); // $ExpectType number
}

// The returned function has a normalized method...
{
	const fcn = xorshift32.factory();
	fcn.normalized(); // $ExpectType number
}

// The compiler throws an error if the function returned by the `factory` method is provided any number of arguments...
{
	const fcn = xorshift32.factory();
	fcn( 1 ); // $ExpectError
	fcn( 2, 1 ); // $ExpectError
	fcn( 2, 1, 1 ); // $ExpectError
}

// The compiler throws an error if the normalized method is provided any arguments...
{
	const fcn = xorshift32.factory();
	fcn.normalized( 1 ); // $ExpectError
	fcn.normalized( 1, 2 ); // $ExpectError
}

// The compiler throws an error if the `factory` method is provided an options argument which is not an object...
{
	xorshift32.factory( null ); // $ExpectError
}

// The compiler throws an error if the `factory` method is provided a `seed` option which is not a valid seed...
{
	xorshift32.factory( { 'seed': true } ); // $ExpectError
	xorshift32.factory( { 'seed': 'abc' } ); // $ExpectError
	xorshift32.factory( { 'seed': null } ); // $ExpectError
	xorshift32.factory( { 'seed': [ 'a' ] } ); // $ExpectError
	xorshift32.factory( { 'seed': {} } ); // $ExpectError
	xorshift32.factory( { 'seed': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the `factory` method is provided a `state` option which is not a valid state...
{
	xorshift32.factory( { 'state': 123 } ); // $ExpectError
	xorshift32.factory( { 'state': 'abc' } ); // $ExpectError
	xorshift32.factory( { 'state': null } ); // $ExpectError
	xorshift32.factory( { 'state': [] } ); // $ExpectError
	xorshift32.factory( { 'state': {} } ); // $ExpectError
	xorshift32.factory( { 'state': true } ); // $ExpectError
	xorshift32.factory( { 'state': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the `factory` method is provided a `copy` option which is not a boolean...
{
	xorshift32.factory( { 'copy': 123 } ); // $ExpectError
	xorshift32.factory( { 'copy': 'abc' } ); // $ExpectError
	xorshift32.factory( { 'copy': null } ); // $ExpectError
	xorshift32.factory( { 'copy': [] } ); // $ExpectError
	xorshift32.factory( { 'copy': {} } ); // $ExpectError
	xorshift32.factory( { 'copy': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the `factory` method is provided more than one argument...
{
	xorshift32.factory( {}, 2 ); // $ExpectError
}

// Test state property...
{
	const fcn = xorshift32.factory();
	const state = fcn.state; // $ExpectType Uint32Array
	fcn.state = state; // Valid assignment
}

// Test readonly properties...
{
	const fcn = xorshift32.factory();
	fcn.NAME; // $ExpectType string
	fcn.MIN; // $ExpectType number
	fcn.MAX; // $ExpectType number
	fcn.seed; // $ExpectType Uint32Array
	fcn.seedLength; // $ExpectType number
	fcn.stateLength; // $ExpectType number
	fcn.byteLength; // $ExpectType number
}

// Test toJSON method...
{
	const fcn = xorshift32.factory();
	fcn.toJSON(); // $ExpectType string
}
